import pathlib,json,gzip,base64
files=json.loads(gzip.decompress(base64.b64decode('')))
for name,text in files.items():
 p=pathlib.Path('v3')/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf8')
pathlib.Path('v3/isolated-results').mkdir(exist_ok=True)
print('Pilot/recovery synthetic source bundle extracted')

